// Preserved Explore scroll offset — HomePage remounts on navigation, so we
// restore where the user left off when they return.
let exploreScrollY = 0;

// ─── Main screen ──────────────────────────────────────────────────────────────
export default function HomePage({ onNavigateToStocks, onNavigateToProfile, onNavigateToPrime, onNavigateToPrimeListing, onNavigateToPrimeStock, onNavigateToPrimeExploreCard, onBuy, primeActivated, positions, initialTab, onInitialTabConsumed, onNativePositionPress }: { onNavigateToStocks: (stock: StockConfig) => void; onNavigateToProfile?: () => void; onNavigateToPrime?: () => void; onNavigateToPrimeListing?: () => void; onNavigateToPrimeStock?: (ticker: string) => void; onNavigateToPrimeExploreCard?: (ticker: string) => void; onBuy?: (o: { name: string; buy: string; stoploss: string; target?: string; market?: string }) => void; primeActivated?: boolean; positions?: Position[]; initialTab?: number | null; onInitialTabConsumed?: () => void; onNativePositionPress?: (p: Position) => void }) {
  const { mode } = useTheme();
  styles = makeStyles();
  useLiveTick(); // re-render the whole screen every 2s so prices jitter
  const [activeTab, setActiveTab] = useState(initialTab ?? 0);
  const [activeNav, setActiveNav] = useState(0);
  const [quotes, setQuotes] = useState<Record<string, Quote>>({});
  const baseRef = useRef<Record<string, Quote>>({});
  const gr1 = useGR1Sheet();
  // Tapped position → detail bottom sheet (null = closed).
  const [selectedPosition, setSelectedPosition] = useState<Position | null>(null);
  const [stripExitToast, setStripExitToast] = useState<{ name: string; qty: number } | null>(null);
  const stripExitToastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const handleStripExit = (name: string, qty: number) => {
    if (stripExitToastTimer.current) clearTimeout(stripExitToastTimer.current);
    setStripExitToast({ name, qty });
    stripExitToastTimer.current = setTimeout(() => setStripExitToast(null), 3000);
  };
  // Names of positions whose SL has been updated from the sheet — their list row
  // reverts to the gem-only state (no "Update" pill).
  const [updatedPositions, setUpdatedPositions] = useState<Set<string>>(new Set());
  const [slSnackbar, setSlSnackbar] = useState<{ name: string; qty: number } | null>(null);

  // We seeded activeTab from initialTab on mount; tell the parent it's been
  // consumed so future returns to Home don't force the tab again.
  useEffect(() => {
    if (initialTab != null) onInitialTabConsumed?.();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Collapse the index strip ("ticker") on scroll so the tabs bar
  // sticks just under the search bar.
  const scrollY = useRef(new Animated.Value(0)).current;
  const exploreScrollRef = useRef<ScrollView>(null);
  const didRestoreScroll = useRef(false);
  const INDEX_STRIP_HEIGHT = 44;
  const stripHeight = scrollY.interpolate({
    inputRange: [0, INDEX_STRIP_HEIGHT],
    outputRange: [INDEX_STRIP_HEIGHT, 0],
    extrapolate: 'clamp',
  });
  const stripOpacity = scrollY.interpolate({
    inputRange: [0, INDEX_STRIP_HEIGHT * 0.6],
    outputRange: [1, 0],
    extrapolate: 'clamp',
  });

  // Fetch real prices from Yahoo Finance every 10 s
  useEffect(() => {
    const fetchAll = async () => {
      const results = await Promise.all(
        ALL_SYMBOLS.map(async (sym) => [sym, await fetchQuote(sym)] as const),
      );
      const map: Record<string, Quote> = {};
      for (const [sym, q] of results) if (q) map[sym] = q;
      if (Object.keys(map).length > 0) {
        baseRef.current = map;
        setQuotes({ ...map });
      }
    };
    fetchAll();
    const id = setInterval(fetchAll, 10_000);
    return () => clearInterval(id);
  }, []);

  // ── helpers ──────────────────────────────────────────────────────────────
  const fmtPrice = (sym: string, fallback: string) => {
    const q = quotes[sym];
    if (!q) return fallback;
    return `₹${q.price.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const fmtChangePct = (sym: string, fallback: string) => {
    const q = quotes[sym];
    if (!q) return fallback;
    const sign = q.changePct >= 0 ? '+' : '';
    return `${sign}${q.changePct.toFixed(2)}%`;
  };

  const isPositive = (sym: string, fallback: boolean) => {
    const q = quotes[sym];
    return q ? q.changePct >= 0 : fallback;
  };

  const fmtIndexChange = (sym: string, fallback: string) => {
    const q = quotes[sym];
    if (!q) return fallback;
    const sign = q.change >= 0 ? '+' : '';
    return `${sign}${q.change.toFixed(2)}`;
  };

  const fmtStockChange = (sym: string, fallback: string) => {
    const q = quotes[sym];
    if (!q) return fallback;
    const sign = q.change >= 0 ? '+' : '';
    const absPct = Math.abs(q.changePct).toFixed(2);
    const absChg = Math.abs(q.change).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    return `${sign}₹${absChg} (${absPct}%)`;
  };

  return (
    <View style={styles.safeArea}>
    <SafeArea style={{ flex: 1 }}>
      <StatusBar barStyle={mode === 'dark' ? 'light-content' : 'dark-content'} backgroundColor={colors.backgroundPrimary} />

      {/* Fixed header */}
      <View style={styles.header}>
        {/* Search bar row */}
        <View style={styles.searchBarRow}>
          <View style={styles.searchBarInner}>
            {/* Groww logo */}
            <View style={styles.growwLogoWrap}>
              <Image source={require('./assets/mds-groww-logo.png')} style={styles.growwLogo} resizeMode="contain" />
            </View>
            {/* Title */}
            <View style={styles.searchTitleWrap}>
              <Text style={styles.searchTitle}>{activeNav === 2 ? 'F&O' : 'Stocks'}</Text>
            </View>
            {/* Actions */}
            <View style={styles.headerActions}>
              <TouchableOpacity style={styles.actionBtn} activeOpacity={0.7}>
                <HugeiconsIcon icon={Search01Icon} size={24} color={colors.contentPrimary} strokeWidth={1.5} />
              </TouchableOpacity>
              <TouchableOpacity style={styles.actionBtn} activeOpacity={0.7} onPress={gr1.openSheet}>
                <GR1Icon size={24} />
              </TouchableOpacity>
              <TouchableOpacity style={styles.profileBtn} activeOpacity={0.8} onPress={onNavigateToProfile}>
                <Image source={ASSETS.profilePic} style={styles.profilePic} />
              </TouchableOpacity>
            </View>
          </View>
        </View>

        {/* Index strip — collapses on scroll */}
        <Animated.View style={{ height: stripHeight, opacity: stripOpacity, overflow: 'hidden' }}>
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            style={styles.indexStrip}
            contentContainerStyle={styles.indexStripContent}
          >
            {INDICES.map((idx, i) => {
              const q = quotes[idx.symbol];
              const baseValue = q ? q.price : priceNum(idx.value);
              const basePts = (idx.positive ? 1 : -1) * priceNum(idx.change);
              const basePct = baseValue ? (basePts / baseValue) * 100 : 0;
              const L = live(baseValue, basePct, idx.symbol, getLiveTick(), 0.12);
              return (
              <View key={idx.name} style={[styles.indexCard, i > 0 && styles.indexCardGap]}>
                <Text style={styles.indexName}>{idx.name}</Text>
                <Text style={styles.indexValue}>{inr(L.price)}</Text>
                <ChangeTag
                  change={`${L.changeAbs >= 0 ? '+' : '-'}${inr(Math.abs(L.changeAbs))}`}
                  positive={L.pos}
                />
              </View>
              );
            })}
          </ScrollView>
        </Animated.View>

        {/* Tabs bar */}
        <View style={styles.tabsBarWrap}>
          <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.tabsBarContent}>
            {TABS.map((tab, i) => (
              <TouchableOpacity key={tab} style={styles.tabItem} onPress={() => setActiveTab(i)} activeOpacity={0.7}>
                <Text style={[styles.tabLabel, i === activeTab && styles.tabLabelActive]}>{tab}</Text>
                {i === activeTab && <View style={styles.tabHighlighter} />}
              </TouchableOpacity>
            ))}
          </ScrollView>
          <View style={styles.tabsDivider} />
        </View>
      </View>

      {/* Scrollable content */}
      <ScrollView
        ref={exploreScrollRef}
        style={styles.scrollView}
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
        scrollEventThrottle={16}
        onScroll={Animated.event(
          [{ nativeEvent: { contentOffset: { y: scrollY } } }],
          { useNativeDriver: false, listener: (e: any) => { exploreScrollY = e.nativeEvent.contentOffset.y; } },
        )}
        onContentSizeChange={() => {
          // Restore the saved offset once, after content is laid out on remount.
          if (!didRestoreScroll.current && exploreScrollY > 0) {
            didRestoreScroll.current = true;
            exploreScrollRef.current?.scrollTo({ y: exploreScrollY, animated: false });
          }
        }}
        onScrollBeginDrag={() => {
          if (!gr1.open) return;
          if (gr1.mode === 'thinking' || gr1.mode === 'answering') {
            gr1.toPeek();
          } else if (gr1.mode === 'suggestions') {
            gr1.closeSheet();
          }
        }}
      >
        {activeNav === 2 ? (
          <View style={{ height: 16 }} />
        ) : activeTab === 2 ? (
          <PositionsTab positions={positions ?? []} onSelect={Platform.OS !== 'web' && onNativePositionPress ? onNativePositionPress : setSelectedPosition} onExitToast={handleStripExit} />
        ) : (
          <>
            {/* Recently viewed */}
            <RecentlyViewedSection onStockPress={onNavigateToStocks} quotes={quotes} />

            {/* Most traded */}
            <MostTradedSection onStockPress={onNavigateToStocks} quotes={quotes} />

            {/* Products and tools */}
            <ProductsAndToolsSection />

        {/* Top movers */}
        <TopMoversSection onStockPress={onNavigateToStocks} quotes={quotes} />

        {/* Prime MTF picks */}
        {primeActivated
          ? <ActivatedPrimeMtfSection onSeeAll={onNavigateToPrimeListing} onCardPress={onNavigateToPrimeExploreCard ?? onNavigateToPrimeStock} onBuy={onBuy} />
          : <PrimeMtfPicksSection onExplore={onNavigateToPrime} />}

        {/* Most traded in MTF */}
        <MostTradedMtfSection onStockPress={onNavigateToStocks} quotes={quotes} />

        {/* Top Intraday */}
        <TopIntradaySection onStockPress={onNavigateToStocks} quotes={quotes} />

        {/* Volume shockers */}
        <VolumeShockersSection />

        {/* Trading screens */}
        <TradingScreensSection />

        {/* Sectors trending today */}
        <SectorsTrendingSection />

        {/* Most bought ETFs */}
        <MostBoughtEtfsSection />

        {/* ETF's by Groww */}
        <GrowwEtfsSection onStockPress={onNavigateToStocks} quotes={quotes} />

        {/* Stocks in news */}
        <StocksInNewsSection onStockPress={onNavigateToStocks} quotes={quotes} />

        <View style={{ height: 16 }} />
          </>
        )}
      </ScrollView>

      <BottomNav activeNav={activeNav} onNavPress={setActiveNav} />
      {stripExitToast && <SellToast name={stripExitToast.name} qty={stripExitToast.qty} />}

    </SafeArea>

      <PositionDetailSheet
        position={selectedPosition}
        onClose={() => setSelectedPosition(null)}
        onUpdate={(p) => setUpdatedPositions((prev) => new Set(prev).add(p.name))}
      />

      <GR1Layer state={gr1} />
      {slSnackbar && (
        <SnackbarSL
          name={slSnackbar.name}
          qty={slSnackbar.qty}
          onDone={() => setSlSnackbar(null)}
        />
      )}
    </View>
  );
}

